import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { rolesKey, rolesPath, useRoles, userRoleKey } from './roles';
import type { Role } from './roles';

type Draft = { user: string; role: string };
const EMPTY: Draft = { user: '', role: '' };

// The roles given on the sheet, and a form that gives a user name a role (clerk, steward, viewer or restricted). Any name not
// listed is a clerk.
function Roles({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const { data: roles = [] } = useRoles(sheet);
  const [draft, setDraft] = useState<Draft>(EMPTY);

  const save = useMutation({
    mutationFn: (body: Draft) => postJson<Role[]>(byUser(rolesPath(sheet), user), body),
    onSuccess: (updated) => {
      queryClient.setQueryData(rolesKey(sheet), updated);
      void queryClient.invalidateQueries({ queryKey: userRoleKey(sheet, user).slice(0, 3) });
      setDraft(EMPTY);
    },
  });
  const send = useSubmitOnce(save);

  const change = (next: Partial<Draft>) => {
    setDraft((d) => ({ ...d, ...next }));
    save.reset();
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    // The server refuses a blank name or a role that is not clerk, steward, viewer or restricted.
    send(draft);
  };

  return (
    <section>
      <h2>Roles</h2>
      <form onSubmit={submit}>
        <label>
          User{' '}
          <input data-testid="role-form-user" value={draft.user} onChange={(e) => change({ user: e.target.value })} />
        </label>{' '}
        <label>
          Role{' '}
          <input
            data-testid="role-form-role"
            placeholder="clerk, steward, viewer or restricted"
            value={draft.role}
            onChange={(e) => change({ role: e.target.value })}
          />
        </label>{' '}
        <button type="submit" data-testid="role-form-submit" disabled={save.isPending}>
          Set role
        </button>
        {save.isError && (
          <span data-testid="role-form-error" role="alert">
            {' '}A role needs a user name and a role of clerk, steward, viewer or restricted.
          </span>
        )}
      </form>
      <ul>
        {roles.map((r) => (
          <li key={r.user} data-testid={`role-row-${r.user}`}>
            <span data-testid="role-user">{r.user}</span>: <span data-testid="role-value">{r.role}</span>
          </li>
        ))}
      </ul>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 7, Component: Roles });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** The role a user name has on the sheet; a name given none is a clerk. A steward settles any due, a clerk
 *  only one at or below the sheet's clerk limit; a viewer sees everything and changes nothing; a restricted user acts as a clerk but lists only the people of
 *  the crews led or joined by the person of their name, and that person. */
export type Role = { user: string; role: 'clerk' | 'steward' | 'viewer' | 'restricted' };

export const rolesKey = (sheet: string) => ['roles', sheet] as const;

export const rolesPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/roles`;

/** Every role given on the sheet, by user name. */
export function useRoles(sheet: string) {
  return useQuery({
    queryKey: rolesKey(sheet),
    queryFn: () => getJson<Role[]>(rolesPath(sheet)),
  });
}

export const userRoleKey = (sheet: string, user: string) => ['roles', sheet, 'of', user] as const;

/** The role the user acts in on the sheet (steward while lent the role), as of the screen's date. */
export function useUserRole(sheet: string, user: string) {
  return useQuery({
    queryKey: userRoleKey(sheet, user),
    queryFn: () => getJson<Role>(`${rolesPath(sheet)}/of?user=${encodeURIComponent(user)}`),
  });
}
